  const worldName = () => `${syl(['Ar', 'Bel', 'Cal', 'Dor', 'Er', 'Fal', 'Gan', 'Hes', 'Il', 'Jor', 'Kal', 'Lor', 'Mer', 'Nor', 'Or', 'Pel', 'Ras', 'Sol', 'Tar', 'Ul', 'Ver', 'Zan'], ['a', 'e', 'i', 'o', 'u'], ['dis', 'gon', 'lia', 'mar', 'nis', 'ra', 'ros', 'tan', 'thea', 've', 'x', 'zar'])()}${pick(['', '', '', '', ' Prime', ' IV', ' Menor', ' Alto'])}`;
